state.done=Array.isArray(state.done)?state.done:[];let current=null,labRedraw=()=>{};
function save(){try{localStorage.setItem('motion-notes-v1',JSON.stringify(state))}catch{toast('浏览器无法保存进度，请导出备份。')}}
function toast(t){$('#toast').textContent=t;$('#toast').style.display='block';setTimeout(()=>$('#toast').style.display='none',2800)}
