function nav(){let q=$('#search').value.trim().toLowerCase(),filter=$('#filter').value;$('#progressText').textContent=`${state.done.length} / ${COURSE.lessons.length} 课已完成`;$('#bar').style.width=100*state.done.length/COURSE.lessons.length+'%';$('#courseNav').innerHTML=COURSE.groups.map((g,i)=>{let ls=COURSE.lessons.filter(l=>l.group===i&&(!filter||l.sources.some(s=>s.includes('Midterm '+filter)))&&(!q||(l.title+l.question+l.body).toLowerCase().includes(q)));return ls.length?`<details ${q||!current||current.group===i?'open':''}><summary>${String(i+1).padStart(2,'0')} · ${g}</summary>${ls.map(l=>`<a href="#${l.id}" class="${current?.id===l.id?'active':''}">${state.done.includes(l.id)?'✓':'○'} ${l.title}</a>`).join('')}</details>`:''}).join('')||'<p>没有匹配的课程。</p>'}
