function markdown(raw){const math=[];raw=raw.replace(/\$\$([\s\S]*?)\$\$|\$([^$\n]+)\$/g,(_,block,inline)=>{const i=math.length;math.push({tex:block??inline,display:block!==undefined});return `MATHSLOT${i}END`});return marked.parse(raw).replace(/MATHSLOT(\d+)END/g,(_,i)=>{try{return katex.renderToString(math[i].tex,{displayMode:math[i].display,throwOnError:true,strict:false})}catch(e){return `<code class="math-error">${esc(math[i].tex)}</code>`}})}
function home(){current=null;$('#toc').innerHTML='';$('#main').innerHTML=`<section class="hero"><div class="eyebrow">A FIELD GUIDE TO ROBOTICS · ECE 470</div><h1>理解空间。<br>让运动<em>变得清晰。</em></h1><p>从一根坐标轴开始，逐步连接旋转、速度、力与轨迹。用直觉理解公式，用交互看见运动。</p><div><span class="pill">中文讲解 · English terminology</span><span class="pill">Midterm 1 + 2</span></div><div class="heroActions"><a class="primary" href="#${state.last||'l01'}">${state.last?'继续学习':'开始第一课'} ↗</a><a class="pill" href="#curriculum">浏览全部课程 ↓</a></div><div class="stats"><div><b>52</b><span>循序渐进的课程</span></div><div><b>12</b><span>知识模块</span></div><div><b>9</b><span>交互实验类型</span></div></div></section><h2 id="curriculum">你的学习路线 <span class="muted" style="font-size:12px">/ 从基础到应用</span></h2><div class="cards">${COURSE.groups.map((g,i)=>{let ls=COURSE.lessons.filter(l=>l.group===i);return `<a class="card" href="#${ls[0].id}"><span class="num">MODULE ${String(i+1).padStart(2,'0')}</span><h3>${g}</h3><p>${ls[0].question}</p><small>${ls.length} 节课 · ${ls.filter(l=>state.done.includes(l.id)).length} 已完成 <span style="float:right">↗</span></small></a>`}).join('')}</div><h2>这门课怎样使用</h2><p class="muted">建议按顺序学习；已经熟悉基础时，可以直接选课。每课从一个问题出发，给出几何直觉、关键公式和短例子。互动实验采用明确的简化模型，帮助理解关系，不代替一般机器人求解器。</p><div class="glossary"><b>统一约定</b><br>右手坐标系；角度计算用弧度。R<sub>sb</sub> 把 b 中的方向坐标变成 s 中的坐标；T<sub>sb</sub> 把 b 中的点坐标变成 s 中的坐标。Twist 按 (ω, v)，wrench 按 (m, f) 排列。</div><footer>内容依据你提供的两份 ECE 470 Study Guide 编排。各课保留来源映射；原课件页码沿用资料，未重新核验原 PDF。<br><a href="README.md">部署与维护说明</a> · <a href="COURSE_MAP.md">知识点覆盖表</a> · <a href="UPDATE_COURSE_PROMPT.md">更新课程的 AI Prompt</a></footer>`;nav()}
function render(){let id=location.hash.slice(1);if(id==='curriculum'){home();$('#curriculum').scrollIntoView();return;}if(!id){home();return}let l=COURSE.lessons.find(l=>l.id===id);if(!l){home();toast('未找到课程，已返回首页');return}current=l;state.last=l.id;save();let idx=COURSE.lessons.indexOf(l);$('#main').innerHTML=`<div class="lessonhead"><a class="eyebrow" href="#">← COURSE OVERVIEW</a><p><span class="pill">${COURSE.groups[l.group]}</span><span class="pill">LESSON ${idx+1} / 52</span><span class="pill">约 ${l.minutes} 分钟</span></p><h1>${l.title}</h1><p class="lead">${l.question}</p><small>${l.sources.join(' · ')}</small></div><div id="labmount"></div><article>${markdown(l.body)}</article><div class="lessonbottom"><button id="prev" ${idx===0?'disabled':''}>← 上一课</button><button class="primary" id="done">${state.done.includes(id)?'✓ 已完成 · 取消标记':'标记本课完成'}</button><button id="next" ${idx===51?'disabled':''}>下一课 →</button></div>`;$('#prev').onclick=()=>location.hash=COURSE.lessons[idx-1].id;$('#next').onclick=()=>location.hash=COURSE.lessons[idx+1].id;$('#done').onclick=()=>{state.done=state.done.includes(id)?state.done.filter(x=>x!==id):[...state.done,id];save();$('#done').textContent=state.done.includes(id)?'✓ 已完成 · 取消标记':'标记本课完成';nav()};let heads=[...document.querySelectorAll('article h2')];heads.forEach((h,i)=>h.id='section-'+i);$('#toc').innerHTML='<div class="eyebrow">ON THIS PAGE</div>'+heads.map(h=>`<a href="javascript:void(0)" data-scroll="${h.id}">${esc(h.textContent)}</a>`).join('')+'<div class="glossary" style="margin-top:24px">s：固定参考系<br>b：随体参考系<br>ω：角速度<br>v：twist 线性分量<br>q：关节坐标</div>';$('#toc').querySelectorAll('[data-scroll]').forEach(a=>a.onclick=()=>document.getElementById(a.dataset.scroll).scrollIntoView());nav();mountLab(idx+1);document.body.classList.remove('menu-open');window.scrollTo(0,0)}
window.onhashchange=render;
