if(kind==='arm'||kind==='ik'){let angles=[];if(kind==='arm')angles=[[rad,b*Math.PI/180]];else{let c=(a*a+b*b-2)/2;if(Math.abs(c)<=1){let q2=Math.acos(c);angles=[q2,-q2].map(q=>[Math.atan2(b,a)-Math.atan2(Math.sin(q),1+Math.cos(q)),q]);}dot(a,b,'#efa778',7)}angles.forEach(([q1,q2],j)=>{let x1=Math.cos(q1),y1=Math.sin(q1),x=x1+Math.cos(q1+q2),y=y1+Math.sin(q1+q2),c=j?'#b3a1ee':accent;line(0,0,x1,y1,c,5);line(x1,y1,x,y,c,5);dot(0,0);dot(x1,y1);dot(x,y,c,7);if(kind==='arm'){let J=[[-Math.sin(q1)-Math.sin(q1+q2),-Math.sin(q1+q2)],[Math.cos(q1)+Math.cos(q1+q2),Math.cos(q1+q2)]],prev=null;for(let t=0;t<=2*Math.PI+.03;t+=.03){let p=[x+.35*(J[0][0]*Math.cos(t)+J[0][1]*Math.sin(t)),y+.35*(J[1][0]*Math.cos(t)+J[1][1]*Math.sin(t))];if(prev)line(...prev,...p,'#efa778',1.8);prev=p}out=`L₁ = L₂ = 1 m；p = (${x.toFixed(3)}, ${y.toFixed(3)})；det J = sin(q₂) = ${Math.sin(q2).toFixed(3)}。<br>橙色曲线是单位关节速度圆经 J 映射的边界（显示缩放 0.35）。把 q₂ 调到 0，看椭圆退化为线段。`}else out+=`分支 ${j+1}：q₁ = ${(q1*180/Math.PI).toFixed(1)}°，q₂ = ${(q2*180/Math.PI).toFixed(1)}°<br>`});if(kind==='ik')out+=(angles.length?'每根杆长 1 m；两种构型到达同一点。在边界两解合并；原点有无穷多解。':'目标距离超过 2 m，不可达。')}
