const bg=$('#particles'),bc=bg.getContext('2d');let frame=0;function animate(){requestAnimationFrame(animate);if(state.noMotion||matchMedia('(prefers-reduced-motion: reduce)').matches){bc.clearRect(0,0,bg.width,bg.height);return}if(++frame%3)return;bg.width=innerWidth;bg.height=innerHeight;bc.fillStyle=state.theme==='light'?'#188c7060':'#7ee6c560';for(let i=0;i<40;i++){let x=(i*173+Math.sin(frame/450+i)*30)%innerWidth,y=(i*137+frame*.045)%innerHeight;bc.beginPath();bc.arc(x,y,i%3===0?1.6:.8,0,7);bc.fill()}}animate();
